<?php
declare(strict_types=1);
require_once __DIR__.'/includes/init.php';require_once __DIR__.'/csrf_helper.php';require_once __DIR__.'/includes/kis_roster.php';
if(!isset($_SESSION['trener_id'])||!canAccess('sync_evidence')){header('Location: login.php');exit;}
function krh(mixed$value):string{return htmlspecialchars((string)$value,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
$errors=[];$actorId=(int)$_SESSION['trener_id'];
if($_SERVER['REQUEST_METHOD']==='POST'){
    if(!csrf_verify((string)($_POST['csrf_token']??'')))$errors[]='Formulář vypršel. Obnovte stránku.';
    else try{$action=(string)($_POST['action']??'');
        if($action==='create_season'){$result=kisRosterCreateSeason($pdo,$actorId,(string)$_POST['code'],(string)$_POST['name'],(string)$_POST['starts_on'],(string)$_POST['ends_on']);$_SESSION['flash_success']='Sezóna '.(string)$result['name'].' je připravena.';}
        elseif($action==='create_team'){$result=kisRosterCreateTeam($pdo,(int)$_POST['season_id'],$actorId,(string)$_POST['code'],(string)$_POST['name'],(string)$_POST['discipline'],(string)$_POST['age_label'],(string)$_POST['note']);$_SESSION['flash_success']='Tým '.(string)$result['name'].' byl vytvořen.';}
        elseif($action==='add_member'){$result=kisRosterAddMember($pdo,(int)$_POST['team_id'],(int)$_POST['sportovec_id'],$actorId,'manual',(string)$_POST['valid_from'],(string)$_POST['note']);$_SESSION['flash_success']=$result['created']?'Sportovec byl přidán na soupisku.':'Sportovec už je na aktivní soupisce.';}
        elseif($action==='remove_member'){$result=kisRosterRemoveMember($pdo,(int)$_POST['member_id'],$actorId,(string)$_POST['valid_to'],(string)$_POST['note']);$_SESSION['flash_success']=$result['changed']?'Sportovec byl ze soupisky odebrán.':'Sportovec už byl odebrán.';}
        else throw new InvalidArgumentException('Neznámá akce soupisky.');
        $target=(int)($_POST['team_id']??0);header('Location: kis_rosters_admin.php'.($target>0?'?team_id='.$target:''));exit;
    }catch(InvalidArgumentException|KisRosterException$exception){$errors[]=$exception->getMessage();}catch(Throwable$exception){error_log('kis_rosters_admin.php: '.$exception->getMessage());$errors[]='Operace selhala bez částečného zápisu.';}
}
$success=(string)($_SESSION['flash_success']??'');unset($_SESSION['flash_success']);$seasons=kisRosterSeasons($pdo);$teams=kisRosterTeams($pdo);$teamId=max(0,(int)($_GET['team_id']??0));$detail=$teamId>0?kisRosterTeamDetail($pdo,$teamId):['team'=>null,'members'=>[],'events'=>[]];$people=$pdo->query("SELECT id,jmeno,prijmeni,narozeni,uciid,stav_clenstvi FROM sportovci WHERE stav_clenstvi<>'archiv' ORDER BY prijmeni,jmeno,id")->fetchAll(PDO::FETCH_ASSOC);$today=(new DateTimeImmutable('today'))->format('Y-m-d');
?>
