<div class="card"><div class="card-header fw-semibold">Nový tým</div><div class="card-body"><form method="post" class="row g-2"><input type="hidden" name="csrf_token" value="<?=krh(csrf_token())?>"><input type="hidden" name="action" value="create_team"><div class="col-12"><label class="form-label">Sezóna</label><select class="form-select" name="season_id" required><option value="">Vyberte</option><?php foreach($seasons as$s):?><option value="<?=(int)$s['id']?>"><?=krh($s['name'])?></option><?php endforeach;?></select></div><div class="col-4"><label class="form-label">Kód</label><input class="form-control" name="code" required></div><div class="col-8"><label class="form-label">Název</label><input class="form-control" name="name" required></div><div class="col-6"><label class="form-label">Disciplína</label><input class="form-control" name="discipline" value="Dráha" required></div><div class="col-6"><label class="form-label">Kategorie</label><input class="form-control" name="age_label" placeholder="U15" required></div><div class="col-12"><label class="form-label">Důvod</label><input class="form-control" name="note" value="Založení interního týmu." required></div><div><button class="btn btn-primary btn-sm">Vytvořit tým</button></div></form></div></div></div>
<div class="col-xl-8"><div class="card mb-3"><div class="card-header fw-semibold">Týmy</div><div class="table-responsive"><table class="table table-sm table-hover mb-0"><thead><tr><th>Sezóna</th><th>Tým</th><th>Disciplína</th><th>Kategorie</th><th>Aktivní</th><th></th></tr></thead><tbody><?php foreach($teams as$t):?><tr><td><?=krh($t['season_name'])?></td><td><?=krh($t['name'])?> <code><?=krh($t['code'])?></code></td><td><?=krh($t['discipline'])?></td><td><?=krh($t['age_label'])?></td><td><?=(int)$t['member_count']?></td><td><a class="btn btn-outline-primary btn-sm" href="?team_id=<?=(int)$t['id']?>">Soupiska</a></td></tr><?php endforeach;?><?php if($teams===[]):?><tr><td colspan="6" class="text-muted">Nejdříve založte sezónu a tým.</td></tr><?php endif;?></tbody></table></div></div>
<?php if($detail['team']):$team=$detail['team'];?><div class="card"><div class="card-header"><strong><?=krh($team['name'])?></strong> · <?=krh($team['season_name'])?> <span class="badge bg-secondary"><?=krh($team['discipline'])?> / <?=krh($team['age_label'])?></span></div><div class="card-body border-bottom"><form method="post" class="row g-2 align-items-end"><input type="hidden" name="csrf_token" value="<?=krh(csrf_token())?>"><input type="hidden" name="action" value="add_member"><input type="hidden" name="team_id" value="<?=(int)$team['id']?>"><div class="col-lg-6"><label class="form-label">Sportovec</label><select class="form-select" name="sportovec_id" required><option value="">Vyberte sportovce</option><?php foreach($people as$p):?><option value="<?=(int)$p['id']?>"><?=krh($p['prijmeni'].' '.$p['jmeno'].' · '.($p['uciid']?:'bez UCI').' · '.$p['stav_clenstvi'])?></option><?php endforeach;?></select></div><div class="col-lg-2"><label class="form-label">Platí od</label><input type="date" class="form-control" name="valid_from" value="<?=krh($today)?>" required></div><div class="col-lg-3"><label class="form-label">Důvod</label><input class="form-control" name="note" value="Ruční zařazení do interní soupisky." required></div><div class="col-lg-1"><button class="btn btn-success btn-sm">Přidat</button></div></form></div><div class="table-responsive"><table class="table table-sm mb-0"><thead><tr><th>Sportovec</th><th>UCI snapshot</th><th>Stav</th><th>Platnost</th><th></th></tr></thead><tbody><?php foreach($detail['members']as$m):?><tr><td><?=krh($m['prijmeni'].' '.$m['jmeno'])?> <span class="small text-muted"><?=krh($m['stav_clenstvi'])?></span></td><td><code><?=krh($m['kis_external_id_snapshot']?:'—')?></code></td><td><?=krh($m['status'])?> / <?=krh($m['source'])?></td><td><?=krh($m['valid_from'])?> – <?=krh($m['valid_to']?:'dosud')?></td><td><?php if($m['status']==='active'):?><form method="post" class="d-flex gap-1"><input type="hidden" name="csrf_token" value="<?=krh(csrf_token())?>"><input type="hidden" name="action" value="remove_member"><input type="hidden" name="team_id" value="<?=(int)$team['id']?>"><input type="hidden" name="member_id" value="<?=(int)$m['id']?>"><input type="hidden" name="valid_to" value="<?=krh($today)?>"><input class="form-control form-control-sm" name="note" value="Odebrání z interní soupisky." required><button class="btn btn-outline-danger btn-sm">Odebrat</button></form><?php endif;?></td></tr><?php endforeach;?><?php if($detail['members']===[]):?><tr><td colspan="5" class="text-muted">Soupiska je prázdná.</td></tr><?php endif;?></tbody></table></div></div><?php endif;?></div></div></main></body></html>
